-- Fern & Ferry: shared trip-planner state.
-- One row, one JSON blob (mirrors the app's existing single-blob shape in
-- src/App.jsx). Public read (so the trip can be shared with friends and
-- family with no login); only authenticated users (invited editors) can
-- write. Realtime is enabled so edits push live to every open browser.

create table if not exists public.app_state (
  id smallint primary key default 1 check (id = 1),
  data jsonb not null,
  updated_at timestamptz not null default now()
);

alter table public.app_state enable row level security;

grant usage on schema public to anon, authenticated;
grant select on public.app_state to anon, authenticated;
grant update on public.app_state to authenticated;

drop policy if exists "app_state_public_read" on public.app_state;
create policy "app_state_public_read"
  on public.app_state
  for select
  using (true);

drop policy if exists "app_state_authenticated_write" on public.app_state;
create policy "app_state_authenticated_write"
  on public.app_state
  for update
  using (auth.role() = 'authenticated')
  with check (auth.role() = 'authenticated');

do $$
begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'app_state'
  ) then
    alter publication supabase_realtime add table public.app_state;
  end if;
end $$;

